raw.css:
:root{--color-bg:#faf7f2;--color-surface:#ffffff;--color-text:#2b2420;--color-text-muted:#5a4f46;--color-border:#d8cfc0;--color-primary:#6b2737;--color-primary-dark:#4a1b27;--color-bg-dark:#2b1620;--color-accent-on-dark:#e8c9a0;--font-heading:Georgia,'Times New Roman',serif;--font-body:Georgia,'Times New Roman',serif;--space-xs:0.5rem;--space-sm:1rem;--space-md:1.5rem;--space-lg:2.5rem;--space-xl:4rem;--radius:0.4rem;--max-width:75rem;}
*{box-sizing:border-box;}
html{font-size:100%;}
body{margin:0;font-family:var(--font-body);background-color:var(--color-bg);color:var(--color-text);line-height:1.6;}
h1,h2,h3{font-family:var(--font-heading);color:var(--color-primary-dark);line-height:1.25;margin-top:0;}
h1{font-size:clamp(1.8rem,4vw,2.6rem);}
h2{font-size:clamp(1.4rem,3vw,1.9rem);}
p{margin-top:0;}
img{max-width:100%;height:auto;display:block;}
a{color:var(--color-primary);text-decoration:underline;}
a:hover{color:var(--color-primary-dark);}
a:focus-visible,button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid var(--color-primary-dark);outline-offset:2px;}
.container{width:100%;max-width:var(--max-width);margin:0 auto;padding-left:1rem;padding-right:1rem;}

/* Header */
header{background-color:var(--color-surface);border-bottom:1px solid var(--color-border);}
.header-inner{display:flex;flex-direction:column;align-items:flex-start;gap:var(--space-sm);padding-top:var(--space-sm);padding-bottom:var(--space-sm);}
.logo{font-family:Georgia,'Times New Roman',serif;text-transform:uppercase;font-size:1.3rem;letter-spacing:0.2em;color:var(--color-primary);text-decoration:none;border-top:3px double var(--color-primary);border-bottom:3px double var(--color-primary);padding:0.3rem 0.6rem;display:inline-block;}
.logo:hover{color:var(--color-primary-dark);}
nav[aria-label="Main"] .nav-list{list-style:none;display:flex;flex-wrap:wrap;gap:var(--space-sm);margin:0;padding:0;}
nav[aria-label="Main"] a{text-decoration:none;color:var(--color-text);font-weight:bold;padding:0.5rem 0.25rem;}
nav[aria-label="Main"] a:hover{color:var(--color-primary);}

/* Footer */
footer{background-color:var(--color-bg-dark);color:var(--color-accent-on-dark);margin-top:var(--space-xl);}
.footer-inner{padding-top:var(--space-lg);padding-bottom:var(--space-lg);text-align:center;}
footer a{color:var(--color-accent-on-dark);}
.footer-name{font-family:var(--font-heading);font-size:1.2rem;letter-spacing:0.1em;margin-bottom:var(--space-xs);}
address{font-style:normal;margin-bottom:var(--space-xs);}
.copyright{font-size:0.9rem;opacity:0.85;}

/* Buttons */
.button{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:0.7rem 1.5rem;background-color:var(--color-primary);color:#ffffff;border:none;border-radius:var(--radius);text-decoration:none;font-weight:bold;font-size:1rem;cursor:pointer;}
.button:hover{background-color:var(--color-primary-dark);}
.button:focus-visible{outline:3px solid var(--color-bg-dark);outline-offset:2px;}

/* Cards */
.card{background-color:var(--color-surface);border:1px solid var(--color-border);border-radius:var(--radius);padding:var(--space-md);}
.card h3{margin-bottom:var(--space-xs);}

/* Grid helper */
.grid{display:grid;gap:var(--space-md);grid-template-columns:1fr;}

/* Sections */
section{padding-top:var(--space-lg);padding-bottom:var(--space-lg);}
.section-dark{background-color:var(--color-bg-dark);color:var(--color-accent-on-dark);}
.section-dark h2{color:var(--color-accent-on-dark);}

/* Forms */
form{display:flex;flex-direction:column;gap:var(--space-md);max-width:34rem;}
.form-field{display:flex;flex-direction:column;gap:0.35rem;}
label{font-weight:bold;}
input,textarea,select{min-height:44px;padding:0.6rem;border:1px solid var(--color-border);border-radius:var(--radius);font-family:inherit;font-size:1rem;background-color:var(--color-surface);color:var(--color-text);}
textarea{min-height:8rem;}
input:focus,textarea:focus,select:focus{border-color:var(--color-primary);}

/* Mobile */
@media (max-width:600px){
  .header-inner{align-items:flex-start;}
  nav[aria-label="Main"] .nav-list{flex-direction:column;gap:0.25rem;}
  .logo{font-size:1.1rem;letter-spacing:0.12em;max-width:100%;}
  section{padding-top:var(--space-md);padding-bottom:var(--space-md);}
}

/* Desktop */
@media (min-width:601px){
  .header-inner{flex-direction:row;align-items:center;justify-content:space-between;}
  .grid-2{grid-template-columns:repeat(2,1fr);}
  .grid-3{grid-template-columns:repeat(3,1fr);}
  form{max-width:40rem;}
}

pages.css:
.home-hero-inner{display:flex;flex-direction:column;gap:var(--space-md);align-items:center;}
.home-hero-text{order:2;}
.home-hero-img{order:1;border-radius:var(--radius);width:100%;}
@media (min-width:601px){
  .home-hero-inner{flex-direction:row;align-items:center;}
  .home-hero-text{order:1;flex:1;}
  .home-hero-img{order:2;flex:1;}
}

.home-book-layout{display:flex;flex-direction:column;gap:var(--space-md);}
.home-book-cover{border-radius:var(--radius);border:1px solid var(--color-border);max-width:16rem;margin:0 auto;}
.home-book-author{font-style:italic;color:var(--color-text-muted);margin-bottom:var(--space-sm);}
@media (min-width:601px){
  .home-book-layout{flex-direction:row;align-items:flex-start;}
  .home-book-cover{margin:0;flex:0 0 16rem;}
  .home-book-details{flex:1;}
}

.home-meeting-card{max-width:40rem;margin:0 auto;background-color:var(--color-surface);color:var(--color-text);}
.home-meeting-list{margin:0 0 var(--space-sm) 0;}
.home-meeting-row{display:flex;flex-direction:column;padding:0.5rem 0;border-bottom:1px solid var(--color-border);}
.home-meeting-row:last-child{border-bottom:none;}
.home-meeting-row dt{font-weight:bold;color:var(--color-primary-dark);}
.home-meeting-row dd{margin:0;}
@media (min-width:601px){
  .home-meeting-row{flex-direction:row;justify-content:space-between;gap:var(--space-md);}
}

.home-join-cta{text-align:center;max-width:40rem;margin:0 auto;}
.home-join-cta p{margin-bottom:var(--space-md);}

